package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class NumberLineSvgRenderer { public String render(NumberLineDiagramSpecV1 s){return render(s,Map.of());} public String render(NumberLineDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),end=s.viewport().width()-p,y=s.viewport().height()/2;double min=num(values,s.minKey(),0),max=num(values,s.maxKey(),10),range=max-min;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(y).append("\" x2=\"").append(end).append("\" y2=\"").append(y).append("\" stroke=\"#000000\"/>");var occupied=new ArrayList<int[]>();for(var point:s.points()){int x=x(num(values,point.positionKey(),min),min,max,p,end);b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"5\" fill=\"").append(point.marker()==PointMarker.CLOSED_CIRCLE?"#000000":"#FFFFFF").append("\" stroke=\"#000000\"/>");if(point.labelTemplate()!=null){int width=Math.max(12,point.labelTemplate().length()*7),height=14;int[] pos=new DeterministicLabelLayout().place(x,y, s.viewport().width(),s.viewport().height(),width,height,occupied);occupied.add(new int[]{pos[0],pos[1]-height,pos[0]+width,pos[1]});b.append("<text x=\"").append(pos[0]).append("\" y=\"").append(pos[1]).append("\">").append(escape(point.labelTemplate())).append("</text>");}}return b.toString();}private int x(double value,double min,double max,int p,int end){return (int)(p+(value-min)/(max==min?1:max-min)*(end-p));}private double num(Map<String,SemanticResolvedValue> v,String k,double d){try{return Double.parseDouble(v.get(k).canonicalValue());}catch(Exception e){return d;}}private String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
